<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <title>Rating Display</title>
  <style>
    .rating-inline {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      margin: 0 0 14px 0;
      font-family: system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
      font-size: 14px;
      font-weight: 600;
      color: #111;
      white-space: nowrap;
      flex-wrap: wrap;
    }
    .stars {
      font-size: 18px;
      color: #fdbc20;
      letter-spacing: 2px;
    }
    .text { color: #444; }
    .sep { color: #cbd5e1; margin: 0 4px; }
    html[lang="ar"] .rating-inline,
    html[dir="rtl"] .rating-inline { direction: rtl; }
  </style>
</head>
<body>
  <div class="rating-inline" role="img" aria-label="{% if is_arabic %}تقييم ٤.٨ من ٥{% else %}4.8 out of 5 stars{% endif %}">
    <span class="stars">★★★★★</span>
    <span class="text">
      {% if is_arabic %}
        ٤.٨/٥ <span class="sep">|</span> موصى بها من أطباء أطفال لبنانيين
      {% else %}
        4.8/5 <span class="sep">|</span> Endorsed by Lebanese Doctors
      {% endif %}
    </span>
  </div>
</body>
</html>

{%- assign is_arabic = false -%}
{%- if request.locale.iso_code contains 'ar' -%}
  {%- assign is_arabic = true -%}
{%- endif -%}
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <style>
    :root{
      --blue:#5aa8e6;
      --blue-soft:#eaf6ff;
      --blue-border:#d7eefc;
      --text:#1f2a37;
      --text-mid:#475569;
      --text-soft:#64748b;
    }
    *{ box-sizing:border-box; }

    .ww-feature-wrap{
      width: 100%;
      padding: 6px 0 0 0;
      font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial;
    }

    /* ===== Bullets ===== */
    .ww-features{
      list-style:none;
      padding:0;
      margin: 0 0 18px 0;
      display:grid;
      gap: 12px;
    }

    .ww-features li{
      display:flex;
      align-items:center;
      gap: 11px;
      font-size: 15.5px;
      line-height: 1.3;
      color: var(--text);
      font-weight: 500;
    }

    .ww-check-circle{
      width: 22px;
      height: 22px;
      flex: 0 0 22px;
      border-radius: 50%;
      background: var(--blue);
      display:inline-grid;
      place-items:center;
      box-shadow: 0 1px 3px rgba(90, 168, 230, 0.28);
    }

    .ww-check-circle svg{
      width: 12px;
      height: 12px;
    }

    /* ===== Stats Card ===== */
    .ww-stats{
      width: 100%;
      background: var(--blue-soft);
      border: 1px solid var(--blue-border);
      border-radius: 14px;
      padding: 16px 8px;
      display:grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 0;
      margin-bottom: 14px;
    }

    .ww-stat{
      display:flex;
      flex-direction:column;
      align-items:center;
      text-align: center;
      gap: 5px;
      padding: 0 6px;
      border-right: 1px solid var(--blue-border);
    }

    .ww-stat:last-child{
      border-right: none;
    }

    .ww-stat-icon{
      width: 26px;
      height: 26px;
      display:grid;
      place-items:center;
      color: var(--blue);
      margin-bottom: 2px;
    }

    .ww-stat-value{
      font-size: 14.5px;
      font-weight: 700;
      color: #1e293b;
      line-height: 1.15;
      letter-spacing: -0.1px;
    }

    .ww-stat-label{
      font-size: 11.5px;
      font-weight: 500;
      color: var(--text-soft);
      line-height: 1.3;
    }

    /* ===== Specs Link ===== */
    .ww-specs-link{
      display: inline-block;
      font-size: 13px;
      font-weight: 500;
      color: var(--text-mid);
      text-decoration: underline;
      text-decoration-color: var(--blue-border);
      text-underline-offset: 3px;
      cursor: pointer;
      transition: color 0.2s, text-decoration-color 0.2s;
    }

    .ww-specs-link:hover{
      color: var(--blue);
      text-decoration-color: var(--blue);
    }

    @media (max-width: 420px){
      .ww-features li{ font-size: 14.5px; }
      .ww-stat-value{ font-size: 13.5px; }
      .ww-stat-label{ font-size: 10.8px; }
    }

    /* ===== RTL ===== */
    html[lang="ar"] .ww-features li,
    html[dir="rtl"] .ww-features li {
      direction: rtl;
      text-align: right;
    }

    html[lang="ar"] .ww-stats,
    html[dir="rtl"] .ww-stats {
      direction: rtl;
    }

    html[lang="ar"] .ww-stat,
    html[dir="rtl"] .ww-stat {
      border-right: none;
      border-left: 1px solid var(--blue-border);
    }

    html[lang="ar"] .ww-stat:last-child,
    html[dir="rtl"] .ww-stat:last-child {
      border-left: none;
    }
  </style>
</head>
<body>
  <div class="ww-feature-wrap">

    <ul class="ww-features">
      <li>
        <span class="ww-check-circle" aria-hidden="true">
          <svg viewBox="0 0 12 12" fill="none">
            <path d="M2 6.5l2.5 2.5L10 3.5" stroke="white" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/>
          </svg>
        </span>
        <span>
          {% if is_arabic %}
            ٣ مرّات إدرار بكل جلسة (تكنولوجيا TriFlow)
          {% else %}
            3 Letdowns Per Session (TriFlow Cycle)
          {% endif %}
        </span>
      </li>

      <li>
        <span class="ww-check-circle" aria-hidden="true">
          <svg viewBox="0 0 12 12" fill="none">
            <path d="M2 6.5l2.5 2.5L10 3.5" stroke="white" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/>
          </svg>
        </span>
        <span>
          {% if is_arabic %}
            حرية كاملة · أيديكِ فاضية للبيبي
          {% else %}
            Truly Hands-Free · Hold Your Baby
          {% endif %}
        </span>
      </li>

      <li>
        <span class="ww-check-circle" aria-hidden="true">
          <svg viewBox="0 0 12 12" fill="none">
            <path d="M2 6.5l2.5 2.5L10 3.5" stroke="white" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/>
          </svg>
        </span>
        <span>
          {% if is_arabic %}
            سيليكون ناعم · ولا وجع
          {% else %}
            Soft Silicone · Zero Pain
          {% endif %}
        </span>
      </li>

      <li>
        <span class="ww-check-circle" aria-hidden="true">
          <svg viewBox="0 0 12 12" fill="none">
            <path d="M2 6.5l2.5 2.5L10 3.5" stroke="white" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/>
          </svg>
        </span>
        <span>
          {% if is_arabic %}
            حليبك بالقنينة · مش حليب صناعي
          {% else %}
            Your Milk · Not Formula
          {% endif %}
        </span>
      </li>

      <li>
        <span class="ww-check-circle" aria-hidden="true">
          <svg viewBox="0 0 12 12" fill="none">
            <path d="M2 6.5l2.5 2.5L10 3.5" stroke="white" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/>
          </svg>
        </span>
        <span>
          {% if is_arabic %}
            موصى بها من أطباء وأخصائيات لبنانيات
          {% else %}
            Endorsed by Lebanese Doctors & IBCLCs
          {% endif %}
        </span>
      </li>
    </ul>

    <div class="ww-stats" role="group" aria-label="Product specs">
      <div class="ww-stat">
        <div class="ww-stat-icon" aria-hidden="true">
          <svg viewBox="0 0 24 24" width="26" height="26" fill="none">
            <rect x="3" y="7" width="16" height="10" rx="2.5" stroke="currentColor" stroke-width="2"/>
            <path d="M21 10v4" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
            <rect x="5.5" y="9.5" width="11" height="5" rx="1" fill="currentColor"/>
          </svg>
        </div>
        <div class="ww-stat-value">
          {% if is_arabic %}
            ٥–٦ جلسات
          {% else %}
            5-6 Sessions
          {% endif %}
        </div>
        <div class="ww-stat-label">
          {% if is_arabic %}
            بكل شحنة كاملة
          {% else %}
            per full charge
          {% endif %}
        </div>
      </div>

      <div class="ww-stat">
        <div class="ww-stat-icon" aria-hidden="true">
          <svg viewBox="0 0 24 24" width="26" height="26" fill="none">
            <path d="M12 2s6 6.5 6 11.2A6 6 0 1 1 6 13.2C6 8.5 12 2 12 2Z"
                  stroke="currentColor" stroke-width="2" stroke-linejoin="round"/>
          </svg>
        </div>
        <div class="ww-stat-value">
          {% if is_arabic %}
            ١٨٠ مل
          {% else %}
            180ml Cup
          {% endif %}
        </div>
        <div class="ww-stat-label">
          {% if is_arabic %}
            ما بيفيض حليبك
          {% else %}
            no overflow
          {% endif %}
        </div>
      </div>

      <div class="ww-stat">
        <div class="ww-stat-icon" aria-hidden="true">
          <svg viewBox="0 0 24 24" width="26" height="26" fill="none">
            <circle cx="12" cy="12" r="6.5" stroke="currentColor" stroke-width="2"/>
            <circle cx="12" cy="4" r="1.3" fill="currentColor"/>
            <circle cx="20" cy="12" r="1.3" fill="currentColor"/>
            <circle cx="12" cy="20" r="1.3" fill="currentColor"/>
            <circle cx="4" cy="12" r="1.3" fill="currentColor"/>
          </svg>
        </div>
        <div class="ww-stat-value">
          {% if is_arabic %}
            ٤ أوضاع
          {% else %}
            4 Modes
          {% endif %}
        </div>
        <div class="ww-stat-label">
          {% if is_arabic %}
            ١٢ مستوى لكل وضع
          {% else %}
            12 levels each
          {% endif %}
        </div>
      </div>
    </div>

    <a href="#full-specs" class="ww-specs-link">
      {% if is_arabic %}
        عرض المواصفات الكاملة والدليل ←
      {% else %}
        View full specs &amp; user manual →
      {% endif %}
    </a>

  </div>
</body>
</html>

