.eid-variant-label { font-size: 12px; font-weight: 600; color: #3D4A5C; }
.eid-swatches { display: flex; gap: 10px; flex-wrap: wrap; }
.eid-swatch {
  width: 32px; height: 32px; border-radius: 50%;
  border: 2px solid #fff; padding: 0; cursor: pointer;
  background-size: cover; background-position: center; background-repeat: no-repeat;
  box-shadow: 0 0 0 1.5px #E5E9EE;
  transition: box-shadow .15s, transform .15s;
  position: relative; overflow: hidden;
  display: inline-flex; align-items: center; justify-content: center;
}
.eid-swatch:hover { box-shadow: 0 0 0 1.5px #B8DCEE; transform: scale(1.05); }
