  background: #ffffff;
  width: 100%;
}

.ww-feature-grid--rtl{
  direction: rtl;
}

.ww-feature-grid__inner{
  max-width: 980px;
  margin: 0 auto;
  padding: 50px 18px;
}

.ww-feature-grid__grid{
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 22px 28px;
}

.ww-feature-grid__item{
  text-align: center;
}

.ww-feature-grid__icon{
  width: 40px;
  height: 40px;
