</style>

{%- assign is_arabic = false -%}
{%- if request.locale.iso_code contains 'ar' -%}
  {%- assign is_arabic = true -%}
{%- endif -%}

<!-- =========================
     DS-WhatToExpect (Square • Premium • Soft Blue Glow)
     DESKTOP LANDSCAPE HERO
     ========================= -->

<section class="ds-expect-glow {% if is_arabic %}ds-expect-glow--rtl{% endif %}" aria-label="{% if is_arabic %}شو تتوقعي{% else %}What to expect{% endif %}">
  <div class="ds-expect-glow__wrap">

    <header class="ds-expect-glow__head">
      <p class="ds-expect-glow__kicker">
        <span class="ds-expect-glow__dot"></span>
        {% if is_arabic %}
          التجربة
        {% else %}
          Experience
        {% endif %}
      </p>

      <h2 class="ds-expect-glow__title">
        {% if is_arabic %}
          شو تتوقعي؟
        {% else %}
          What to Expect
        {% endif %}
      </h2>

      <p class="ds-expect-glow__sub">
        {% if is_arabic %}
          أداء ناعم، ثابت، ومريح بكل استخدام.
        {% else %}
          Refined performance. Calm consistency.
        {% endif %}
      </p>
    </header>
  </div>

  <!-- FULL-BLEED IMAGE -->
  <div class="ds-expect-glow__hero" aria-hidden="true">
    <img
      class="ds-expect-glow__heroImg"
      src="https://cdn.shopify.com/s/files/1/0847/2120/5545/files/weewondersbreastpumpmodelusing.png?v=1771072852"
      alt=""
      loading="lazy"
    />
  </div>

  <div class="ds-expect-glow__wrap">
    <div class="ds-expect-glow__grid">

      <article class="ds-expect-glow__card">
        <div class="ds-expect-glow__top">
          <span class="ds-expect-glow__num">01</span>
          <span class="ds-expect-glow__tag">
            {% if is_arabic %}راحة{% else %}Comfort{% endif %}
          </span>
        </div>
        <h3 class="ds-expect-glow__label">
          {% if is_arabic %}بداية ناعمة{% else %}Gentle Start{% endif %}
        </h3>
        <p class="ds-expect-glow__text">
          {% if is_arabic %}
            بتبلّش تدريجياً وبنعومة لتعطيكِ إحساس طبيعي ومريح من أول لحظة.
          {% else %}
            A smooth ramp-up designed to feel natural from the first moment.
          {% endif %}
        </p>
      </article>

      <article class="ds-expect-glow__card">
        <div class="ds-expect-glow__top">
          <span class="ds-expect-glow__num">02</span>
          <span class="ds-expect-glow__tag">
            {% if is_arabic %}خفيفة{% else %}Discreet{% endif %}
          </span>
        </div>
        <h3 class="ds-expect-glow__label">
          {% if is_arabic %}صوت هادئ{% else %}Quiet Feel{% endif %}
        </h3>
        <p class="ds-expect-glow__text">
          {% if is_arabic %}
            أداء هادئ وناعم بيندمج بسهولة بروتينك اليومي من دون ما يكون ملفت.
          {% else %}
            Subtle performance that blends seamlessly into your routine.
          {% endif %}
        </p>
      </article>

      <article class="ds-expect-glow__card">
        <div class="ds-expect-glow__top">
          <span class="ds-expect-glow__num">03</span>
          <span class="ds-expect-glow__tag">
            {% if is_arabic %}تحكّم{% else %}Control{% endif %}
          </span>
        </div>
        <h3 class="ds-expect-glow__label">
          {% if is_arabic %}تعديل سهل{% else %}Easy Adjustments{% endif %}
        </h3>
        <p class="ds-expect-glow__text">
          {% if is_arabic %}
            فيكِ تعدّلي كل جلسة شفط بسهولة وبحسب اللي بيريّحك.
          {% else %}
            Fine-tune each session with simple, precise control.
          {% endif %}
        </p>
      </article>

      <article class="ds-expect-glow__card">
        <div class="ds-expect-glow__top">
          <span class="ds-expect-glow__num">04</span>
          <span class="ds-expect-glow__tag">
            {% if is_arabic %}عناية{% else %}Care{% endif %}
          </span>
        </div>
        <h3 class="ds-expect-glow__label">
          {% if is_arabic %}تنظيف بسيط{% else %}Simple Cleanup{% endif %}
        </h3>
        <p class="ds-expect-glow__text">
          {% if is_arabic %}
            قطع قليلة وتنظيف سريع بعد كل استخدام، من دون تعقيد.
          {% else %}
            Minimal parts and effortless washing after every use.
          {% endif %}
        </p>
      </article>

    </div>
  </div>
</section>

<style>
/* =========================
   DS-Expect Glow
   ========================= */

.ds-expect-glow{
  --accent: #7ac8f0;
  --text: #000;
  --muted: rgba(0,0,0,.62);
  --line: rgba(0,0,0,.10);

  background: #fff;
  color: var(--text);
  padding: clamp(36px, 5vw, 80px) 0;
  overflow-x: hidden;
}

.ds-expect-glow--rtl{
  direction: rtl;
}

.ds-expect-glow__wrap{
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 clamp(18px, 4vw, 32px);
}

/* Header */

.ds-expect-glow__head{
  max-width: 760px;
  margin-bottom: clamp(24px, 3vw, 40px);
}

.ds-expect-glow--rtl .ds-expect-glow__head{
  text-align: right;
  margin-left: auto;
}

.ds-expect-glow__kicker{
  display: inline-flex;
  align-items: center;
  gap: 10px;
  margin: 0 0 12px;
  font-size: 12px;
  letter-spacing: .25em;
  text-transform: uppercase;
  color: rgba(0,0,0,.55);
}

.ds-expect-glow--rtl .ds-expect-glow__kicker{
  letter-spacing: .08em;
}

.ds-expect-glow__dot{
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--accent);
  box-shadow: 0 0 0 4px rgba(122,200,240,.18);
}

.ds-expect-glow__title{
  margin: 0 0 10px;
  font-size: clamp(34px, 4vw, 60px);
  font-weight: 600;
  letter-spacing: -0.03em;
  line-height: 1.05;
}

.ds-expect-glow__sub{
  margin: 0;
  font-size: 15px;
  line-height: 1.6;
  color: var(--muted);
}

/* =========================
   FULL-BLEED HERO IMAGE
   ========================= */

.ds-expect-glow__hero{
  position: relative;
  left: 50%;
  right: 50%;
  margin-left: -50vw;
  margin-right: -50vw;
  width: 100vw;
  margin-bottom: 32px;
}

/* Desktop landscape */
@media (min-width: 990px){
  .ds-expect-glow__heroImg{
    width: 100vw;
    aspect-ratio: 16 / 9;
    height: auto;
    object-fit: cover;
    display: block;
  }
}

/* Mobile keeps taller feel */
@media (max-width: 989px){
  .ds-expect-glow__heroImg{
    width: 100vw;
    height: 450px;
    object-fit: cover;
    display: block;
  }
}

/* Grid */

.ds-expect-glow__grid{
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: clamp(14px, 2vw, 24px);
}

.ds-expect-glow__card{
  position: relative;
  padding: clamp(20px, 2.8vw, 30px);
  border-radius: 0;
  border: 1px solid var(--line);
  background: #fff;
  min-height: 185px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.ds-expect-glow__card::before{
  content:"";
  position:absolute;
  top:-60px;
  right:-60px;
  width:220px;
  height:220px;
  background: radial-gradient(circle at 30% 30%, rgba(122,200,240,.28), transparent 65%);
  pointer-events:none;
}

.ds-expect-glow--rtl .ds-expect-glow__card::before{
  right:auto;
  left:-60px;
}

.ds-expect-glow__top{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  margin-bottom:16px;
}

.ds-expect-glow__num{
  font-size:12px;
  letter-spacing:.18em;
  color:rgba(0,0,0,.50);
}

.ds-expect-glow__tag{
  font-size:11px;
  letter-spacing:.12em;
  text-transform:uppercase;
  padding:7px 10px;
  border-radius:999px;
  border:1px solid rgba(122,200,240,.35);
  background: rgba(122,200,240,.10);
  color:rgba(0,0,0,.60);
}

.ds-expect-glow--rtl .ds-expect-glow__tag{
  letter-spacing: 0;
}

.ds-expect-glow__label{
  margin:0 0 10px;
  font-size: clamp(16px, 1.3vw, 20px);
  font-weight:600;
}

.ds-expect-glow__text{
  margin:0;
  font-size:14px;
  line-height:1.65;
  color:var(--muted);
  max-width:40ch;
}

.ds-expect-glow--rtl .ds-expect-glow__label,
.ds-expect-glow--rtl .ds-expect-glow__text{
  text-align: right;
}

@media (max-width: 749px){
  .ds-expect-glow__grid{
    grid-template-columns: 1fr;
  }
}
</style>

{%- assign is_arabic = false -%}
{%- if request.locale.iso_code contains 'ar' -%}
  {%- assign is_arabic = true -%}
{%- endif -%}

<!-- ===== DS-HowTo (Minimal / Luxury) ===== -->
<section class="ds-howto {% if is_arabic %}ds-howto--rtl{% endif %}" aria-label="{% if is_arabic %}طريقة الاستخدام{% else %}How to use{% endif %}">
  <div class="ds-howto__wrap">
    <header class="ds-howto__head">
      <p class="ds-howto__eyebrow">
        {% if is_arabic %}
          دليل سريع
        {% else %}
          Quick Guide
        {% endif %}
      </p>

      <h2 class="ds-howto__title">
        {% if is_arabic %}
          طريقة الاستخدام
        {% else %}
          How to Use
        {% endif %}
      </h2>

      <p class="ds-howto__sub">
        {% if is_arabic %}
          خطوات بسيطة. تنظيف سهل. وشفط مريح.
        {% else %}
          Minimal steps. Clean. Comfortable. Done.
        {% endif %}
      </p>
    </header>
  </div>

  <!-- FULL-BLEED image -->
  <div class="ds-howto__hero" aria-hidden="true">
    <img
      class="ds-howto__heroImg"
      src="https://cdn.shopify.com/s/files/1/0847/2120/5545/files/10.jpg?v=1771948376"
      alt=""
      loading="lazy"
    />
  </div>

  <div class="ds-howto__wrap">
    <ol class="ds-howto__steps">
      <li class="ds-howto__step">
        <span class="ds-howto__badge">01</span>
        <div class="ds-howto__content">
          <p class="ds-howto__label">
            {% if is_arabic %}ركّبي القطع{% else %}Assemble{% endif %}
          </p>
          <p class="ds-howto__text">
            {% if is_arabic %}
              الصمام ← القطع السيليكون ← الفلانج ← المحرّك.
            {% else %}
              Valve → diaphragm → flange → motor.
            {% endif %}
          </p>
        </div>
      </li>

      <li class="ds-howto__step">
        <span class="ds-howto__badge">02</span>
        <div class="ds-howto__content">
          <p class="ds-howto__label">
            {% if is_arabic %}ثبّتيها صح{% else %}Position{% endif %}
          </p>
          <p class="ds-howto__text">
            {% if is_arabic %}
              حطي الحلمة بالنص وتأكدي إنو في إحكام كامل.
            {% else %}
              Center the nipple. Create a full seal.
            {% endif %}
          </p>
        </div>
      </li>

      <li class="ds-howto__step">
        <span class="ds-howto__badge">03</span>
        <div class="ds-howto__content">
          <p class="ds-howto__label">
            {% if is_arabic %}بلّشي{% else %}Start{% endif %}
          </p>
          <p class="ds-howto__text">
            {% if is_arabic %}
              كبسة مطوّلة على زر التشغيل لتبلّشي الشفط.
            {% else %}
              Long-press power to begin.
            {% endif %}
          </p>
        </div>
      </li>

      <li class="ds-howto__step">
        <span class="ds-howto__badge">04</span>
        <div class="ds-howto__content">
          <p class="ds-howto__label">
            {% if is_arabic %}عدّلي المستوى{% else %}Adjust{% endif %}
          </p>
          <p class="ds-howto__text">
            {% if is_arabic %}
              استخدمي + و − لتوصلي للمستوى اللي بيريّحك.
            {% else %}
              Use + / − to reach a comfortable level.
            {% endif %}
          </p>
        </div>
      </li>

      <li class="ds-howto__step">
        <span class="ds-howto__badge">05</span>
        <div class="ds-howto__content">
          <p class="ds-howto__label">
            {% if is_arabic %}خلّصي ونضّفي{% else %}Finish{% endif %}
          </p>
          <p class="ds-howto__text">
            {% if is_arabic %}
              كبسة مطوّلة لتوقفيها. سكبي الحليب ونضّفي القطع.
            {% else %}
              Long-press power to stop. Pour &amp; clean.
            {% endif %}
          </p>
        </div>
      </li>
    </ol>

    <div class="ds-howto__note" role="note">
      <p class="ds-howto__noteText">
        {% if is_arabic %}
          نصيحة: بلّشي على مستوى ناعم، وبعدها زيدي تدريجياً. الراحة أولاً.
        {% else %}
          Tip: Start gentle, then increase gradually. Comfort first.
        {% endif %}
      </p>
    </div>
  </div>
</section>

<style>
  .ds-howto{
    --accent: #7ac8f0;
    --text: #000;
    --muted: rgba(0,0,0,.62);
    --line: rgba(0,0,0,.10);
    --panel: rgba(122,200,240,.14);
    background: #fff;
    color: var(--text);
    padding: clamp(28px, 4vw, 64px) 0;
    overflow-x: hidden;
  }

  .ds-howto--rtl{
    direction: rtl;
  }

  .ds-howto__wrap{
    max-width: 1080px;
    margin: 0 auto;
    padding: 0 clamp(16px, 4vw, 28px);
  }

  .ds-howto__head{
    max-width: 680px;
    margin-bottom: clamp(18px, 2.4vw, 28px);
  }

  .ds-howto--rtl .ds-howto__head{
    text-align: right;
    margin-left: auto;
  }

  .ds-howto__eyebrow{
    margin: 0 0 10px;
    font-size: 12px;
    letter-spacing: .22em;
    text-transform: uppercase;
    color: var(--muted);
  }

  .ds-howto--rtl .ds-howto__eyebrow{
    letter-spacing: .04em;
  }

  .ds-howto__title{
    margin: 0 0 10px;
    font-weight: 520;
    letter-spacing: -0.02em;
    line-height: 1.05;
    font-size: clamp(28px, 3.8vw, 52px);
    color: #000;
  }

  .ds-howto__sub{
    margin: 0;
    font-size: 15px;
    line-height: 1.55;
    color: var(--muted);
  }

  .ds-howto__title::after{
    content: "";
    display: block;
    width: 64px;
    height: 2px;
    margin-top: 14px;
    background: var(--accent);
    border-radius: 999px;
    opacity: .9;
  }

  .ds-howto--rtl .ds-howto__title::after{
    margin-left: auto;
  }

  .ds-howto__hero{
    position: relative;
    left: 50%;
    right: 50%;
    margin-left: -50vw;
    margin-right: -50vw;
    width: 100vw;
    margin-bottom: 18px;
  }

  @media (min-width: 990px){
    .ds-howto__heroImg{
      display: block;
      width: 100vw;
      aspect-ratio: 16 / 9;
      height: auto;
      object-fit: cover;
    }
  }

  @media (max-width: 989px){
    .ds-howto__heroImg{
      display: block;
      width: 100vw;
      height: 450px;
      object-fit: cover;
    }
  }

  .ds-howto__steps{
    list-style: none;
    padding: 0;
    margin: 0;
    border-top: 1px solid var(--line);
  }

  .ds-howto__step{
    display: grid;
    grid-template-columns: 70px 1fr;
    gap: 14px;
    padding: 18px 0;
    border-bottom: 1px solid var(--line);
    align-items: center;
  }

  .ds-howto--rtl .ds-howto__step{
    grid-template-columns: 1fr 70px;
  }

  .ds-howto--rtl .ds-howto__badge{
    grid-column: 2;
    grid-row: 1;
  }

  .ds-howto--rtl .ds-howto__content{
    grid-column: 1;
    grid-row: 1;
    text-align: right;
  }

  .ds-howto__badge{
    width: 52px;
    height: 52px;
    border-radius: 999px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: var(--panel);
    border: 1px solid rgba(122,200,240,.35);
    color: #000;
    font-size: 12px;
    letter-spacing: .12em;
    font-variant-numeric: tabular-nums;
  }

  .ds-howto__label{
    margin: 0 0 6px;
    font-size: 15px;
    font-weight: 520;
    letter-spacing: -0.01em;
    color: #000;
  }

  .ds-howto__text{
    margin: 0;
    font-size: 14px;
    line-height: 1.55;
    color: var(--muted);
  }

  .ds-howto__note{
    margin-top: 16px;
    padding: 14px 16px;
    border-radius: 14px;
    background: #fff;
    border: 1px solid rgba(122,200,240,.45);
  }

  .ds-howto__noteText{
    margin: 0;
    font-size: 13.5px;
    line-height: 1.55;
    color: rgba(0,0,0,.72);
  }

  .ds-howto--rtl .ds-howto__noteText{
    text-align: right;
  }

  @media (max-width: 640px){
    .ds-howto{
      padding: 34px 0;
    }

    .ds-howto__head{
      margin-bottom: 16px;
    }

    .ds-howto__step{
      grid-template-columns: 56px 1fr;
      padding: 16px 0;
    }

    .ds-howto--rtl .ds-howto__step{
      grid-template-columns: 1fr 56px;
    }

    .ds-howto__badge{
      width: 44px;
      height: 44px;
      font-size: 11px;
    }

    .ds-howto__sub{
      font-size: 14px;
    }
  }
</style>
